from taf.collectors.core.templates.dynamic_class_creation import Creating
from taf.collectors.core.factories.named_factory import Factory
from taf.converters.base import FilePatternFinder, OutputFileMapper, OutputPathMapper
from .converter import TsharkConverter


class TsharkConverterFactory(Creating("executor", "LocalExecutor"), Factory):
    _optional_parameters = {"options", "tshark_path", "name"}
    _product_class = TsharkConverter

    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        """
        Builds the arguments for the constructor call

        :param configuration: Configuration information of converters
        :param dict existing_arguments:
            existing arguments for the final constructor call, that don't need to be created
            (dict with constructor parameter name as key and argument value as value)
        :param dict resulting_arguments:
            resulting arguments for the final constructor call
            (dict with constructor parameter name as key and argument value as value)
        """
        super(TsharkConverterFactory, self)._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        for parameter_name in ["options", "tshark_path", "binary"]:
            if parameter_name in configuration:
                resulting_arguments[parameter_name] = configuration[parameter_name]
        resulting_arguments["finder"] = FilePatternFinder(
            file_path_pattern=configuration["file_path_pattern"])
        resulting_arguments["mapper"] = OutputPathMapper(
            output_directory=configuration["output_directory"],
            output_extension=configuration["output_extension"]) if configuration.get("output_directory") \
            else OutputFileMapper(output_extension=configuration["output_extension"])
